# girth BFS
from collections import deque
best=10**9
for s in range(n):
    dist=[-1]*n; par=[-1]*n
    dist[s]=0; q=deque([s])
    while q:
        u=q.popleft()
        for v in adj[u]:
            if dist[v]<0:
                dist[v]=dist[u]+1; par[v]=u; q.append(v)
            elif par[u]!=v and par[v]!=u:
                best=min(best, dist[u]+dist[v]+1)
